  consequence: { example: 'Missing the deadline may have serious consequences.', translation: '错过截止日期可能会带来严重后果。' },
  consult: { example: 'You should consult your doctor before changing the treatment.', translation: '在改变治疗方案前，你应该咨询医生。' },
  consumer: { example: 'Consumers need clear information before choosing a service.', translation: '消费者在选择服务前需要清晰的信息。' },
  contact: { example: 'Please contact me if you need any further information.', translation: '如需更多信息，请联系我。' },
  contract: { example: 'Please read the contract carefully before you sign it.', translation: '签字前请仔细阅读合同。' },
