  '短语类|away 短语|take away': { example: 'The waiter took away our plates after the meal.', translation: '用餐后，服务员收走了我们的盘子。', split: 'take away + 名词（拿走）；代词放中间：take it away；英式名词 takeaway 指外卖' },
  '短语类|back 短语|bring back': { example: 'This photograph brings back happy memories of my childhood.', translation: '这张照片唤起了我童年的美好回忆。', split: 'bring back（带回/归还/使想起）；bring back memories（唤起回忆）' },
  '短语类|back 短语|call (sb.) back': { example: 'The manager is in a meeting, but she will call you back this afternoon.', translation: '经理正在开会，但她今天下午会给你回电话。', split: 'call somebody back（给某人回电话）；代词放中间：call me back' },
  '短语类|back 短语|come back': { example: 'Please come back tomorrow when the service desk is open.', translation: '请明天服务台开放时再回来。', split: 'come back（回来）；come → came → come；不能说 come back to here' },
  '短语类|back 短语|get back': { example: 'What time did you get back from the airport last night?', translation: '你昨晚几点从机场回来的？', split: 'get back（返回/取回）；get back from + 地点；get something back（取回某物）' },
  '短语类|back 短语|give back': { example: 'You must give back the library books by Friday.', translation: '你必须在星期五前归还图书馆的书。', split: 'give back + 名词（归还）；give something back to someone；代词放中间' },
