  '短语类|固定搭配|do some cleaning': { example: 'We need to do some cleaning before the guests arrive.', translation: '客人到达前，我们需要打扫一下。', split: 'do some cleaning（做清洁）；类似搭配：do some shopping/reading' },
  '短语类|固定搭配|do the dishes': { example: 'I will do the dishes if you prepare dinner.', translation: '如果你准备晚饭，我就洗碗。', split: 'do the dishes（洗餐具，美式常用）；英式也常说 wash up' },
