  '第十八天|网络|screen': { example: 'A confirmation message will appear on the screen.', translation: '屏幕上会出现确认信息。', split: 'computer screen（电脑屏幕）；touch screen（触摸屏）；on screen（在屏幕上）' },
  '第十八天|网络|search': { example: 'Use the search box to find courses in your area.', translation: '请使用搜索框查找所在地区的课程。', split: 'search for（搜索……）；search box（搜索框）；search result（搜索结果）' },
  '第十八天|网络|computer': { example: 'You can use a computer free of charge at the library.', translation: '你可以在图书馆免费使用电脑。', split: 'computer（电脑）→ computing（计算机技术）；computer skills（电脑技能）' },
