  '第十八天|网络|e-mail': { example: 'Please e-mail the document to the course administrator.', translation: '请把文件通过电子邮件发送给课程管理员。', split: 'e-mail/email 可作名词或动词；email address（电子邮箱地址）' },
  '第十八天|网络|online': { example: 'Applications must be completed online this year.', translation: '今年申请必须在网上完成。', split: 'online 可作形容词或副词；online form/course（在线表格/课程）' },
