  '第十七天|方位|direction': { example: 'Ask at reception for directions to the meeting room.', translation: '请在接待处询问前往会议室的路线。', split: 'direction（方向/路线指示）；directions 常表示“路线说明”；direct（直接的）' },
  '第十七天|方位|centre': { example: 'The information desk is in the centre of the main hall.', translation: '咨询台位于主大厅中央。', split: 'in the centre of（在……中央）；centre 是英式拼写，美式为 center' },
