  '第十七天|方位|middle': { example: 'A small garden lies in the middle of the housing estate.', translation: '住宅区中央有一个小花园。', split: 'in the middle of（在……中间）；middle seat（中间座位）' },
  '第十七天|方位|bottom': { example: 'Sign your name at the bottom of the form.', translation: '请在表格底部签名。', split: 'at the bottom of（在……底部）；bottom shelf（最下层架子）' },
  '第十七天|方位|top': { example: 'The reference number is printed at the top of the letter.', translation: '编号印在信件顶部。', split: 'at the top of（在……顶部）；top floor（顶层）' },
  '第十七天|方位|surface': { example: 'Place the box on a flat, dry surface.', translation: '请把箱子放在平坦干燥的表面上。', split: 'on the surface（在表面）；road surface（路面）；surface 也可作动词“浮现”' },
  '第十七天|方位|east': { example: 'The railway station is east of the town centre.', translation: '火车站位于镇中心以东。', split: 'east of（在……以东）；in the east of（在……东部范围内）' },
  '第十七天|方位|west': { example: 'Most of the new housing is west of the river.', translation: '大部分新住宅位于河流以西。', split: 'west of（在……以西）；western（西部的）' },
  '第十七天|方位|south': { example: 'The airport is about ten kilometres south of the city.', translation: '机场位于城市以南约十公里处。', split: 'south of（在……以南）；southern（南部的）' },
