  '第十七天|方位|beside': { example: 'The ticket machine is beside the main entrance.', translation: '售票机在正门旁边。', split: 'beside = next to（在……旁边）；辨析 besides（此外/除……之外）' },
  '第十七天|方位|behind': { example: 'The visitor car park is behind the office building.', translation: '访客停车场在办公楼后面。', split: 'behind（在……后面）↔ in front of（在……前面）' },
  '第十七天|方位|up': { example: 'Go up the stairs to the reception desk on the first floor.', translation: '请上楼前往二楼的接待台。', split: 'go up（向上走）；upstairs（在楼上）；英国 first floor 对应中文二楼' },
  '第十七天|方位|down': { example: 'Walk down the corridor until you reach the lift.', translation: '沿走廊一直走，直到电梯处。', split: 'walk/go down（沿……向前/向下走）；downstairs（在楼下）' },
  '第十七天|方位|back': { example: 'Step back from the platform edge when the train approaches.', translation: '火车进站时，请从站台边缘向后退。', split: '此处 back 是副词“向后”；go back（返回）；step back（后退）' },
