  '第三天|家人与亲友|raise': { example: 'They raised three children in a small coastal town.', translation: '他们在一个海滨小镇养育了三个孩子。', split: '搭配：raise a child（养育孩子）；注意 raise 是及物动词' },
  '第三天|家人与亲友|marriage': { example: 'Their marriage has remained strong for more than twenty years.', translation: '他们的婚姻二十多年来一直很稳固。', split: 'marry（结婚）→ marriage（婚姻，y 变 i）' },
  '第三天|家人与亲友|marry': { example: 'They plan to marry after they have saved enough for a home.', translation: '他们计划在攒够买房的钱后结婚。', split: 'marry someone（与某人结婚）；be married to someone（与某人已婚）' },
  '第三天|家人与亲友|friend': { example: 'A friend recommended this childcare centre to me.', translation: '一位朋友向我推荐了这家托儿中心。', split: '词族：friend（朋友）→ friendly（友好的）→ friendship（友谊）' },
  '第三天|其他人|human': { example: 'Clean water is a basic human need.', translation: '清洁的水是人类的基本需求。', split: '搭配：human being（人类）；human rights（人权）' },
  '第三天|其他人|people': { example: 'Many people in the area travel to work by bus.', translation: '这个地区的许多人乘公交车上班。', split: 'people 通常是 person 的复数；不说 many peoples 表示“许多人”' },
  '第三天|其他人|person': { example: 'Only one person may enter the interview room at a time.', translation: '每次只能有一个人进入面试室。', split: '单数 person；常用复数 people' },
