  '第三天|其他人|baby': { example: 'The hotel can provide a cot for the baby at no extra cost.', translation: '酒店可以免费为婴儿提供一张婴儿床。', split: '单数 baby；复数 babies（y 变 ies）' },
  '第三天|其他人|elder': { example: 'Children are taught to listen respectfully to their elders.', translation: '孩子们被教导要尊重地听长辈讲话。', split: 'elder 常作名词表示长辈；elderly 常作形容词表示年长的' },
  '第三天|其他人|lady': { example: 'The lady at the ticket office explained the fare options.', translation: '售票处的女士解释了不同票价选择。', split: '单数 lady；复数 ladies（y 变 ies）' },
  '第三天|其他人|miss': { example: 'Please ask Miss Lee to call me when she returns.', translation: '李小姐回来后，请让她给我打电话。', split: 'Miss + 姓氏，用于称呼未婚女性；句中通常首字母大写' },
